design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:82:          "content": "import { Box, Button, IconButton, Stack, Tooltip, Typography } from '@mui/material'\nimport CalendarOutline from 'mdi-material-ui/CalendarOutline'\nimport ArrowCollapseVertical from 'mdi-material-ui/ArrowCollapseVertical'\nimport ArrowExpandVertical from 'mdi-material-ui/ArrowExpandVertical'\nimport Close from 'mdi-material-ui/Close'\nimport Play from 'mdi-material-ui/Play'\nimport ArrowUpwardOutlined from '@mui/icons-material/ArrowUpwardOutlined'\nimport CheckOutlined from '@mui/icons-material/CheckOutlined'\nimport StopOutlined from '@mui/icons-material/StopOutlined'\nimport type { ActionContext } from '../../data/action_context'\nimport type { ActionExecutionStatus } from '../../data/action_run_types'\nimport { CUSTOM_PROMPT_ACTION_ID, type ActionDefinition } from '../../data/action_types'\nimport type { AgentConversation } from '../../data/data_types'\nimport { worktreeService } from '../../services/project/worktree_service'\nimport { ResizablePopper } from '../resizable_popper'\nimport { WorktreeSelector, type WorktreeAssignment, type WorktreeAssignmentTarget } from '../worktree_selector'\nimport { ActionAgentPresetName } from './action_agent_preset_name'\nimport { ActionAgentPrompt } from './action_agent_prompt'\nimport { ActionAgentQuestion } from './action_agent_question'\nimport { ActionAgentSelectors } from './action_agent_selectors'\nimport { ActionConversationChat } from './action_conversation_chat'\nimport { ActionConversationPicker } from './action_conversation_picker'\nimport { ActionLogErrorDisplay } from './action_log_error_display'\nimport { ActionPhraseButtons } from './action_phrase_buttons'\nimport { statusColor } from './action_popup_defaults'\nimport { ActionRunHistory } from './action_run_history'\nimport { ActionRunStatus } from './action_run_status'\nimport { ActionScheduleForm } from './action_schedule_form'\nimport { ActionSelector } from './action_selector'\nimport { ActionUsageSummary } from './action_usage_summary'\nimport { useActionPopupController } from './use_action_popup_controller'\n\nexport const CARD_RUN_POPUP_SIZE_STORAGE_KEY = 'md2.cardRunPopupSize'\nexport const PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY = 'md2.projectAgentPopupSize'\nconst MIN_CHAT_HEIGHT = 96\n\ninterface ActionPopupContentProps {\n    activeActionStatuses: Record<string, ActionExecutionStatus>\n    action: ActionDefinition\n    actions: ActionDefinition[]\n    anchorElement: HTMLElement | null\n    assignmentContext: ActionContext\n    baseContext: ActionContext\n    draggable?: boolean\n    fullHeight: boolean\n    onAddAction: () => void\n    onClose: () => void\n    onConversationViewed?: (conversation: AgentConversation) => void\n    onSelectAction: (actionId: string) => void\n    onToggleFullHeight: () => void\n    open: boolean\n    primaryPath: string | null\n    showSaveControls: boolean\n    titleId: string\n    unseenResultActionIds?: string[]\n}\n\n/**\n * The message is rebuilt on every render but only reads the worktree list on the failing\n * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.\n */\nfunction worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {\n    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError\n    if (!hasWorktreeAssignment && !action.needsWorkTree) return null\n    if (context.kind !== 'card' && context.kind !== 'project') {\n        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for worktree execution'\n        return `Action \"${action.label}\" requires card or project context ${reason}`\n    }\n    if (context.worktreeError) return context.worktreeError\n    if (context.worktree === undefined) return `Action \"${action.label}\" requires a worktree assignment`\n    if (!/^[1-9]\\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`\n\n    const worktree = Number.parseInt(context.worktree, 10)\n    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`\n    const record = worktreeService.getRecords()[worktree - 1]\n    if (!record) return `Configured worktree ${worktree} does not exist`\n    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`\n\n    return null\n}\n\nfunction worktreeAssignmentTarget(context: ActionContext): WorktreeAssignmentTarget | null {\n    if (context.kind === 'project') return { kind: 'project' }\n    if ((context.kind === 'card' || context.kind === 'file') && context.file) return { kind: 'card', path: context.file }\n\n    return null\n}\n\n/** Presentation and execution behavior for the internally selected popup action. */\nexport function ActionPopupContent(props: ActionPopupContentProps) {\n    const {\n        action, actions, activeActionStatuses, anchorElement, assignmentContext, baseContext, draggable, fullHeight, onAddAction, onClose,\n        onSelectAction, onToggleFullHeight, open, primaryPath, showSaveControls, titleId, unseenResultActionIds = [],\n    } = props\n    const controller = useActionPopupController({\n        action,\n        context: assignmentContext,\n        scheduleContext: baseContext,\n        enableConversations: action.type === 'agent',\n        executionValidationError: worktreeValidationMessage(action, assignmentContext),\n    })\n    const promptRequired = action.id === CUSTOM_PROMPT_ACTION_ID\n    const sessionActive = controller.runStatus === 'queued'\n        || controller.runStatus === 'running'\n        || controller.runStatus === 'waitingForInput'\n    const showAgentInteraction = action.type === 'agent' || controller.agentActive\n    const showAgentSend = sessionActive ? controller.agentActive : action.type === 'agent'\n    const showCommandRun = !sessionActive && action.type === 'command'\n    const sizeStorageKey = baseContext.kind === 'project'\n        ? PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY\n        : CARD_RUN_POPUP_SIZE_STORAGE_KEY\n    const handlePrimaryRun = showSaveControls ? controller.handleSaveAndRun : controller.handleRun\n    const showUsageSummary = baseContext.kind === 'card' && !!baseContext.file\n    const runDisabled = !!controller.executionDisabledMessage\n        || controller.promptPreparationPending\n        || controller.promptPreparationFailed\n        || (promptRequired && controller.prompt.trim().length === 0)\n        || (controller.agentActive && (\n            !controller.interactionReady\n            || controller.prompt.trim().length === 0\n            || !!controller.structuredQuestion\n        ))\n        || (sessionActive && !controller.agentActive)\n        || (showSaveControls && controller.saveDisabled)\n    const parsedWorktree = assignmentContext.worktree && /^[1-9]\\d*$/u.test(assignmentContext.worktree)\n        ? Number.parseInt(assignmentContext.worktree, 10)\n        : null\n    const worktreeAssignment: WorktreeAssignment = {\n        worktree: parsedWorktree,\n        worktreeError: assignmentContext.worktreeError ?? null,\n        worktreeValue: assignmentContext.worktree ?? null,\n    }\n    const assignmentTarget = baseContext.kind === 'card' || baseContext.kind === 'file' || baseContext.kind === 'project'\n        ? worktreeAssignmentTarget(baseContext)\n        : null\n\n    return (\n        <ResizablePopper\n            anchorElement={anchorElement}\n            draggable={draggable}\n            fullHeight={fullHeight}\n            initialSize={{ height: 450, width: 400 }}\n            labelId={titleId}\n            onClose={onClose}\n            open={open}\n            paperSx={{\n                bgcolor: 'background.paper',\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: '14px',\n                boxShadow: '0 24px 60px rgba(16,24,40,0.28)',\n                flexDirection: 'column',\n            }}\n            resizeFromAllSides\n            resizeLabel=\"Resize action popup\"\n            storageKey={sizeStorageKey}\n        >\n            <Typography\n                id={titleId}\n                sx={{ clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', height: 1, overflow: 'hidden', position: 'absolute', whiteSpace: 'nowrap', width: 1 }}\n            >\n                Run actions\n            </Typography>\n            <Box\n                data-drag-handle={draggable ? 'true' : undefined}\n                sx={{\n                    borderBottom: 1, borderColor: 'divider', cursor: draggable ? 'move' : undefined,\n                    display: 'flex', flexDirection: 'column', gap: 1, px: 1.5, py: 1.5,\n                }}\n            >\n                <Box data-testid=\"action-popup-toolbar\" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>\n                    {assignmentTarget ? (\n                        <WorktreeSelector\n                            assignment={worktreeAssignment}\n                            assignmentTarget={assignmentTarget}\n                            disabled={sessionActive}\n                            primaryPath={primaryPath}\n                        />\n                    ) : null}\n                    {action.type === 'agent' ? (\n                        <ActionConversationPicker\n                            conversations={controller.conversations}\n                            disabled={sessionActive}\n                            loading={controller.conversationHistoryLoading}\n                            onChange={controller.handleConversationChange}\n                            selectedPath={controller.displayedConversation?.path ?? ''}\n                        />\n                    ) : null}\n                    <Box sx={{ flex: 1 }} />\n                    <Tooltip title={fullHeight ? 'Collapse downward' : 'Expand upward'}>\n                        <IconButton\n                            aria-label={fullHeight ? 'Collapse downward' : 'Expand upward'}\n                            onClick={onToggleFullHeight}\n                            size=\"small\"\n                            sx={{ flexShrink: 0, height: 30, width: 30 }}\n                        >\n                            {fullHeight ? <ArrowCollapseVertical sx={{ fontSize: 18 }} /> : <ArrowExpandVertical sx={{ fontSize: 18 }} />}\n                        </IconButton>\n                    </Tooltip>\n                    <IconButton aria-label=\"Close\" onClick={onClose} size=\"small\" sx={{ flexShrink: 0, height: 30, width: 30 }}>\n                        <Close sx={{ fontSize: 18 }} />\n                    </IconButton>\n                </Box>\n                <ActionSelector\n                    activeActionStatuses={activeActionStatuses}\n                    adding={showSaveControls}\n                    actions={actions}\n                    onAdd={onAddAction}\n                    onSelect={onSelectAction}\n                    selectedAction={action}\n                    unseenResultActionIds={unseenResultActionIds}\n                />\n            </Box>\n            <Stack spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>\n                {showAgentInteraction ? (\n                    <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>\n                        {showSaveControls ? (\n                            <ActionAgentPresetName\n                                actionLabel={controller.actionLabel}\n                                onActionLabelChange={controller.handleActionLabelChange}\n                                onRunShortcut={runDisabled ? undefined : handlePrimaryRun}\n                            />\n                        ) : null}\n                        <Box sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', flexWrap: 'wrap', fontSize: 12, gap: 0.75 }}>\n                            {action.type === 'agent' ? (\n                                <ActionAgentSelectors\n                                    agent={controller.agent}\n                                    agentAvailability={controller.agentAvailability}\n                                    agentProfiles={controller.agentProfiles}\n                                    disabled={sessionActive}\n                                    model={controller.model}\n                                    onAgentChange={controller.handleAgentChange}\n                                    onModelChange={controller.handleModelChange}\n                                    onThinkingLevelChange={controller.handleThinkingLevelChange}\n                                    selectedAgentModels={controller.selectedAgentModels}\n                                    thinkingLevel={controller.thinkingLevel}\n                                />\n                            ) : null}\n                            <ActionLogErrorDisplay logs={controller.runLogs} />\n                        </Box>\n                        <Box sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowY: 'auto' }}>\n                            <ActionConversationChat\n                                conversation={controller.displayedConversation}\n                                onConversationViewed={props.onConversationViewed}\n                                status={controller.runStatus}\n                            />\n                        </Box>\n                        <ActionAgentPrompt\n                            convertMessage={controller.convertMessage}\n                            disabled={false}\n                            onPromptChange={controller.handlePromptChange}\n                            onRunShortcut={runDisabled ? undefined : handlePrimaryRun}\n                            prompt={controller.prompt}\n                            promptFailed={controller.promptPreparationFailed}\n                            promptLoading={controller.promptPreparationPending}\n                            promptResetToken={controller.promptResetToken}\n                        />\n                        {controller.structuredQuestion ? (\n                            <ActionAgentQuestion\n                                onAnswer={controller.handleAnswerQuestion}\n                                questions={controller.structuredQuestion.questions}\n                            />\n                        ) : null}\n                    </Stack>\n                ) : null}\n                {controller.isFollowUp && action.phrases.length > 0 ? (\n                    <ActionPhraseButtons\n                        onDoubleClick={controller.handlePhraseDoubleClick}\n                        onSelect={controller.handlePhraseSelect}\n                        phrases={action.phrases}\n                    />\n                ) : null}\n                {controller.scheduleOpen ? (\n                    <ActionScheduleForm\n                        message={controller.scheduleMessage}\n                        onRegister={controller.handleScheduleAction}\n                        onTimestampChange={controller.handleScheduleTimestampChange}\n                        timestamp={controller.scheduleTimestamp}\n                    />\n                ) : null}\n                {action.type !== 'agent' && controller.runStatus !== 'idle' ? (\n                    <ActionRunStatus\n                        color={statusColor(controller.runStatus)}\n                        logs={controller.runLogs}\n                        status={controller.runStatus}\n                    />\n                ) : null}\n                {controller.executionDisabledMessage ? (\n                    <Typography color=\"text.secondary\" role=\"note\" variant=\"caption\">\n                        {controller.executionDisabledMessage}\n                    </Typography>\n                ) : null}\n                {controller.executionValidationError ? (\n                    <Typography color=\"error.main\" role=\"alert\" variant=\"caption\">\n                        {controller.executionValidationError}\n                    </Typography>\n                ) : null}\n                {action.type !== 'agent' ? (\n                    <ActionRunHistory compact entries={controller.history} error={controller.historyError} />\n                ) : null}\n            </Stack>\n            <Box sx={{ alignItems: 'center', bgcolor: 'background.default', borderTop: 1, borderColor: 'divider', display: 'flex', gap: 1, px: 2, py: 1.5 }}>\n                {showUsageSummary && action.type === 'agent' && assignmentContext.cardInternalId ? (\n                    <ActionUsageSummary\n                        actionId={action.id}\n                        cardInternalId={assignmentContext.cardInternalId}\n                        conversations={controller.conversations}\n                        history={controller.history}\n                    />\n                ) : null}\n                <Box sx={{ flex: 1 }} />\n                {sessionActive ? (\n                    <Tooltip title=\"Stop\">\n                        <span>\n                            <IconButton\n                                aria-label=\"Stop\"\n                                disabled={!controller.backendAvailable}\n                                onClick={controller.handleCancel}\n                                size=\"small\"\n                            >\n                                <StopOutlined sx={{ fontSize: 18 }} />\n                            </IconButton>\n                        </span>\n                    </Tooltip>\n                ) : null}\n                {controller.manualFinishAvailable ? (\n                    <Tooltip title=\"Finish\">\n                        <span>\n                            <IconButton\n                                aria-label=\"Finish\"\n                                disabled={!controller.backendAvailable || !controller.interactionReady}\n                                onClick={controller.handleFinish}\n                                size=\"small\"\n                            >\n                                <CheckOutlined sx={{ fontSize: 18 }} />\n                            </IconButton>\n                        </span>\n                    </Tooltip>\n                ) : null}\n                {showSaveControls ? (\n                    <Button disabled={controller.saveDisabled} onClick={controller.handleConvertToAction} size=\"small\" variant=\"outlined\">\n                        Save\n                    </Button>\n                ) : null}\n                <Button\n                    disabled={sessionActive || !controller.backendAvailable}\n                    onClick={controller.handleToggleSchedule}\n                    size=\"small\"\n                    startIcon={<CalendarOutline sx={{ fontSize: '14px !important' }} />}\n                    sx={{\n                        bgcolor: 'background.paper',\n                        borderColor: 'divider',\n                        color: 'text.secondary',\n                        height: 34,\n                        '&:hover': { borderColor: 'primary.main', color: 'primary.main' },\n                    }}\n                    variant=\"outlined\"\n                >\n                    Schedule\n                </Button>\n                {showAgentSend ? (\n                    <Tooltip title=\"Send\">\n                        <span>\n                            <IconButton\n                                aria-label=\"Send\"\n                                color=\"primary\"\n                                disabled={runDisabled}\n                                onClick={handlePrimaryRun}\n                                size=\"small\"\n                            >\n                                <ArrowUpwardOutlined sx={{ fontSize: 18 }} />\n                            </IconButton>\n                        </span>\n                    </Tooltip>\n                ) : showCommandRun ? (\n                    <Button\n                        disabled={runDisabled}\n                        onClick={handlePrimaryRun}\n                        size=\"small\"\n                        startIcon={<Play sx={{ fontSize: '13px !important' }} />}\n                        sx={{ height: 34, px: 2 }}\n                        variant=\"contained\"\n                    >\n                        Run\n                    </Button>\n                ) : null}\n            </Box>\n        </ResizablePopper>\n    )\n}\n\r\n",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:136:          "content": "---\nid: F-052\ntitle: agent popup conversation layout, history picker and full-height mode\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 9929944d-5218-4bdc-bdf8-f7e3fdf59723\n---\n\n## Goal\n\nMake the agent popup read like a chat: show the selected conversation above the prompt, replace the inline agent run-history list with a conversation picker, and allow the popup to expand to the full application height.\n\n## Current state\n\n`ActionPopup` is shared by the card `Run` entry point and the project agent FAB. In its card-run layout, `ActionAgentForm` renders the Agent, Model and Thinking selectors followed immediately by the prompt. `ActionRunStatus` is rendered below the form and shows phase summaries rather than the persisted conversation messages. `ActionRunHistory` then renders every action-history entry inline.\n\nAction history is keyed by action id and context and stores output summaries; an entry has no conversation reference and therefore cannot load a chat. Persisted `AgentConversation` records already contain `startedAt`, `title`, `messages` and `path`, but card conversations are discovered through the card's `agents` frontmatter and project-scoped conversations have no equivalent listing contract. The parser also replaces a missing conversation title with its id, so the UI cannot currently distinguish an explicit title from a fallback.\n\n## Implementation details\n\n### Agent popup layout\n\n- Apply the new layout to agent actions in both shared popup entry points: card `Run` and the project agent FAB. Command-action history and its diff controls keep their current behavior.\n- Keep Agent, Model and Thinking on one control row. Add a conversation-history dropdown on that row and align it to the right.\n- Below the controls, show the selected conversation as an ordered chat log using its user and assistant messages. The active run continues to stream into this area; lifecycle, tool and error events may be shown where relevant without replacing the message transcript with phase summaries.\n- Place a divider below the chat log and the prompt input below the divider. Empty/new conversations show an empty chat area without an inline run-history placeholder.\n- Starting a new conversation selects its live log. Selecting a persisted conversation loads it by reference and replaces the displayed chat log. If the user continues that conversation, pass the selected conversation `path` through the existing `continueFrom` flow; do not continue a different or merely most-recent conversation.\n- Loading failures use `dialogService` and leave the previously selected conversation visible.\n\n### Conversation history dropdown\n\n- Replace `ActionRunHistory` in the agent popup with the dropdown; do not derive the picker from `ActionRunHistoryEntry` summaries.\n- Each item represents exactly one persisted `AgentConversation` belonging to the popup context. Card popups include conversations whose stable `cardInternalId` matches the card. Project popups include project-scoped conversations whose `cardInternalId` is `null`. Do not mix conversations from another card or scope.\n- Sort conversations newest first by `startedAt` and display the date and local time for every item.\n- When the log contains a non-empty explicit `title`, use it as the item text and show the date/time with it. Without an explicit title, use the date/time as the item text. Preserve whether the title was explicit during parsing instead of presenting the current id fallback as a title.\n- Add a listing/loading boundary that works for local Git, GitHub and remote-control storage. Card frontmatter references can remain the card discovery source; project scope needs an explicit way to discover its conversation references. Keep path validation and stable `cardInternalId` ownership checks.\n- Refresh the picker after a run is persisted. A running conversation may appear immediately, but it must not be duplicated when the persisted record arrives.\n\n### Full-height mode\n\n- Add an `Expand upward` icon button immediately before the existing Close button in the popup header.\n- Expanding detaches the popup's positioning from its FAB or card `Run` anchor while retaining the selected action and context. Position its top and bottom edges at the application viewport edges so it occupies the full application height; preserve its current width and horizontal position within the viewport.\n- In full-height mode, replace the expand button with a `Collapse downward` button. Height resize handles are inactive while expanded.\n- Collapsing reattaches the popup to its original anchor and restores the exact pre-expansion size and placement. Full-height dimensions must not overwrite the separately persisted normal sizes for card and project-agent popups.\n- Closing from full-height mode closes normally. Reopening starts in normal anchored mode. Resizing the application while expanded keeps the popup constrained to the application height.\n\n## Affected components\n\n- `app/src/components/actions/action_popup.tsx`: header controls, agent-only layout, selected chat and expanded state.\n- `app/src/components/actions/action_agent_form.tsx`: separate the selector row and prompt so the chat and divider can sit between them without duplicating form behavior.\n- `app/src/components/actions/use_action_popup_controller.ts`: conversation selection/loading, refresh and continuation reference.\n- `app/src/components/actions/action_run_history.tsx`: remains for command actions; it is no longer rendered for agent actions.\n- `app/src/components/resizable_popper.tsx`: support a controlled full-height detached presentation while preserving normal anchored size.\n- Agent conversation types, parsers and storage/bridge implementations: retain explicit-title information and list conversations for the requested context.\n\n## Edge cases\n\n- An empty history leaves the dropdown empty/disabled and still allows a new run.\n- Invalid dates fall back to the stored timestamp text rather than hiding the conversation.\n- Switching actions reloads and selects history for the new action/context; a late response from the previous selection must not replace it.\n- A selected failed or cancelled conversation remains readable. Continuation availability follows the existing provider/session rules.\n- Expanding a card-linked popup changes only presentation; it does not lose or broaden the card context.\n\n## Acceptance criteria\n\n- In an agent popup, the selected/live chat is above the prompt and a divider separates them.\n- Agent, Model and Thinking remain on one row, with a right-aligned conversation dropdown.\n- Every dropdown item shows local date and time; an explicit log title is used as its label when present.\n- Selecting an item loads that single conversation into the chat, and continuing uses that conversation's reference.\n- Card and project popups show only conversations owned by their context and refresh without duplicates after a run.\n- Agent popups no longer show the inline `ActionRunHistory`; command history and diff behavior are unchanged.\n- The header shows Expand immediately before Close. Expand fills the application height and detaches from the anchor; Collapse restores the original anchored size and placement.\n- Tests cover layout order, divider placement, title/date fallback labels, sorting, context filtering, selection races and errors, continuation reference, history refresh, expand/collapse restoration, viewport resizing, and both card and FAB entry points.\n- App and desktop lint, typecheck and tests pass.\n\n## See also\n\n- `design/architecture/initial description/action_popup.md`\n- `design/feature_descriptions/F_049_agent_chat_fab_popup.md`\n- `design/feature_descriptions/ready/F_047_running_actions_and_agents.md`\n- `design/feature_descriptions/ready/F_050_one_shot_agent_conversations.md`\n- `design/feature_descriptions/ready/F_033_agent_and_model_selection.md`\n\r\n",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:160:          "content": "72:function belongsToContext(conversation: AgentConversation, context: ActionContext) {\n74:        ? conversation.cardInternalId === null\n75:        : conversation.cardInternalId === context.cardInternalId\n78:function belongsToAction(conversation: AgentConversation, actionId: string, context: ActionContext) {\n79:    return belongsToContext(conversation, context) && conversation.actionId === actionId\n82:function conversationTimestamp(conversation: AgentConversation) {\n83:    const timestamp = Date.parse(conversation.startedAt)\n88:function conversationContextKey(actionId: string, context: ActionContext) {\n99:    const assistantMessageId = `${turn.conversationId}-assistant-draft`\n100:    const liveMessageIds = new Set(turn.messages.map(({ id }) => id))\n101:    const priorMessages = (base?.messages ?? []).filter(({ id }) => !liveMessageIds.has(id) && id !== assistantMessageId)\n102:    const messages = [\n104:        ...turn.messages,\n112:    const conversationStatus = status === 'queued' || status === 'running' || status === 'waitingForInput'\n127:        id: turn.conversationId,\n128:        messages,\n132:        status: conversationStatus,\n139:    conversations: AgentConversation[],\n145:    for (const conversation of conversations) {\n146:        if (belongsToAction(conversation, actionId, context)) byId.set(conversation.id, conversation)\n150:    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))\n173:    const promptContextKey = conversationContextKey(action.id, context)\n188:    const [conversationHistoryState, setConversationHistoryState] = useState<{ conversations: AgentConversation[], key: string }>({ conversations: [], key: '' })\n207:    const [selectedConversationState, setSelectedConversationState] = useState<{ conversation: AgentConversation | null, key: string }>({ conversation: null, key: '' })\n234:    const conversationKey = promptContextKey\n245:    const selectionKey = `${conversationKey}\\u0000${input.continueFrom ?? ''}`\n246:    const conversationHistory = conversationHistoryState.key === conversationKey ? conversationHistoryState.conversations : []\n247:    const conversationHistoryLoading = !!input.enableConversations && conversationHistoryState.key !== conversationKey\n248:    const selectedConversation = selectedConversationState.key === selectionKey ? selectedConversationState.conversation : null\n249:    const selectedHistory = selectedConversation ? [...conversationHistory, selectedConversation] : conversationHistory\n251:    const runStatus = sharedExecution?.status ?? localRunStatus\n253:    const sessionActive = runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'\n260:        : liveActionKey === conversationKey || runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'\n263:        ? selectedHistory.find(({ id }) => id === sharedAgentTurn.conversationId) ?? null\n273:    const displayedConversation = liveConversation ?? selectedConversation\n274:    const conversations = mergeConversationHistory(selectedHistory, action.id, context, liveConversation)\n280:        && (streamingActive || (runStatus !== 'queued' && runStatus !== 'running' && runStatus !== 'waitingForInput' && !!continuationReference))\n332:            setConversationHistoryState({ conversations: loadedConversations, key: conversationKey })\n334:            dialogService.error(error, { fallbackMessage: 'Could not refresh agent conversations' })\n351:                setConversationHistoryState({ conversations: loadedConversations, key: conversationKey })\n353:                    setSelectedConversationState({ conversation: null, key: selectionKey })\n357:                const conversation = await loadConversation(input.continueFrom)\n359:                if (!belongsToContext(conversation, activeContext)) throw new Error('Selected agent conversation belongs to another context')\n360:                if (conversation.actionId !== action.id) throw new Error('Selected agent conversation belongs to another action')\n361:                setSelectedConversationState({ conversation, key: selectionKey })\n364:                    setConversationHistoryState({ conversations: [], key: conversationKey })\n365:                    setSelectedConversationState({ conversation: null, key: selectionKey })\n366:                    dialogService.error(error, { fallbackMessage: 'Could not load agent conversations' })\n379:        conversationKey,\n410:        if (action.type === 'agent') setLiveActionKey(conversationKey)\n504:            const conversation = await loadConversation(path)\n506:            if (!belongsToContext(conversation, context)) throw new Error('Selected agent conversation belongs to another context')\n507:            if (conversation.actionId !== action.id) throw new Error('Selected agent conversation belongs to another action')\n509:            setSelectedConversationState({ conversation, key: selectionKey })\n513:                dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })\n632:        || runStatus === 'queued'\n633:        || runStatus === 'running'\n634:        || runStatus === 'waitingForInput'\n647:        conversationHistoryLoading,\n648:        conversations,\n649:        displayedConversation,\n680:        runStatus,\n",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:166:          "content": "import { useEffect, useRef, useState } from 'react'\r\nimport type { ChangeEvent } from 'react'\r\nimport { actionContextIdentity } from '../../data/action_context'\r\nimport type { ActionContext } from '../../data/action_context'\r\nimport type { ActionDefinition } from '../../data/action_types'\r\nimport { hasExecutionBackend, type ActionRunHistoryEntry } from '../../data/electron_action_bridge'\r\nimport {\r\n    defaultModelForProfile,\r\n    findAgentProfile,\r\n    mergeAgentProfiles,\r\n    type ThinkingLevel,\r\n    validateThinkingLevel,\r\n} from '../../data/agent_profiles'\r\nimport type { ActionExecutionStatus, ActionRunResult } from '../../data/action_run_types'\r\nimport type { AgentConversation } from '../../data/data_types'\r\nimport { actionExecutionService, type LiveAgentTurn } from '../../services/actions/action_execution_service'\r\nimport { dialogService } from '../../services/dialog_service'\r\nimport { useActionExecution } from '../hooks/use_action_executions'\r\nimport { useConfigValueOrFallback } from '../hooks/use_config_value'\r\nimport { useAgentCapabilities } from '../hooks/use_agent_capabilities'\r\nimport {\r\n    defaultCancelAction,\r\n    defaultAnswerQuestion,\r\n    defaultConvertPromptToAction,\r\n    defaultLoadConversation,\r\n    defaultLoadConversations,\r\n    defaultLoadHistory,\r\n    defaultPreparePrompt,\r\n    defaultFinishAction,\r\n    defaultRunAction,\r\n    defaultSendMessage,\r\n    defaultScheduleAction,\r\n    type CancelAction,\r\n    type AnswerQuestion,\r\n    type ConvertPromptToAction,\r\n    type LoadConversation,\r\n    type LoadConversations,\r\n    type LoadHistory,\r\n    type FinishAction,\r\n    type PopupRunStatus,\r\n    type PreparePrompt,\r\n    type RunAction,\r\n    type SendMessage,\r\n    type ScheduleAction,\r\n} from './action_popup_defaults'\r\nimport { createScheduleTrigger } from './action_schedule_trigger'\r\n\r\nconst DEFAULT_CONVERT_LABEL_LENGTH = 40\r\ntype PromptPreparationStatus = 'failed' | 'loading' | 'ready'\r\n\r\ninterface ActionPopupControllerInput {\r\n    action: ActionDefinition\r\n    answerQuestion?: AnswerQuestion\r\n    cancelAction?: CancelAction\r\n    continueFrom?: string\r\n    context: ActionContext\r\n    convertPromptToAction?: ConvertPromptToAction\r\n    enableConversations?: boolean\r\n    executionValidationError?: string | null\r\n    finishAction?: FinishAction\r\n    initialPrompt?: string\r\n    loadConversation?: LoadConversation\r\n    loadConversations?: LoadConversations\r\n    loadHistory?: LoadHistory\r\n    preparePrompt?: PreparePrompt\r\n    runAction?: RunAction\r\n    sendMessage?: SendMessage\r\n    scheduleContext?: ActionContext\r\n    scheduleAction?: ScheduleAction\r\n}\r\n\r\nfunction belongsToContext(conversation: AgentConversation, context: ActionContext) {\r\n    return context.kind === 'project'\r\n        ? conversation.cardInternalId === null\r\n        : conversation.cardInternalId === context.cardInternalId\r\n}\r\n\r\nfunction belongsToAction(conversation: AgentConversation, actionId: string, context: ActionContext) {\r\n    return belongsToContext(conversation, context) && conversation.actionId === actionId\r\n}\r\n\r\nfunction conversationTimestamp(conversation: AgentConversation) {\r\n    const timestamp = Date.parse(conversation.startedAt)\r\n\r\n    return Number.isNaN(timestamp) ? 0 : timestamp\r\n}\r\n\r\nfunction conversationContextKey(actionId: string, context: ActionContext) {\r\n    return `${actionId}\\u0000${actionContextIdentity(context)}`\r\n}\r\n\r\nfunction liveAgentConversation(\r\n    turn: LiveAgentTurn,\r\n    actionId: string,\r\n    context: ActionContext,\r\n    status: ActionExecutionStatus,\r\n    base: AgentConversation | null,\r\n): AgentConversation {\r\n    const assistantMessageId = `${turn.conversationId}-assistant-draft`\r\n    const liveMessageIds = new Set(turn.messages.map(({ id }) => id))\r\n    const priorMessages = (base?.messages ?? []).filter(({ id }) => !liveMessageIds.has(id) && id !== assistantMessageId)\r\n    const messages = [\r\n        ...priorMessages,\r\n        ...turn.messages,\r\n        ...(turn.assistantText.length > 0 ? [{\r\n            content: turn.assistantText,\r\n            id: assistantMessageId,\r\n            role: 'assistant' as const,\r\n            timestamp: turn.startedAt,\r\n        }] : []),\r\n    ]\r\n    const conversationStatus = status === 'queued' || status === 'running' || status === 'waitingForInput'\r\n        ? status === 'queued' ? 'running' : status\r\n        : status === 'cancelled'\r\n            ? 'cancelled'\r\n            : status === 'failed'\r\n                ? 'failed'\r\n                : 'completed'\r\n\r\n    return {\r\n        actionId,\r\n        cardInternalId: context.cardInternalId ?? null,\r\n        cardPath: context.file ?? null,\r\n        completedAt: null,\r\n        events: base?.events ?? [],\r\n        hasExplicitTitle: base?.hasExplicitTitle ?? true,\r\n        id: turn.conversationId,\r\n        messages,\r\n        path: turn.reference,\r\n        providerSessions: base?.providerSessions ?? [],\r\n        startedAt: base?.startedAt ?? turn.startedAt,\r\n        status: conversationStatus,\r\n        title: base?.title ?? turn.title,\r\n        ...(base?.usage ? { usage: base.usage } : {}),\r\n    }\r\n}\r\n\r\nexport function mergeConversationHistory(\r\n    conversations: AgentConversation[],\r\n    actionId: string,\r\n    context: ActionContext,\r\n    liveConversation: AgentConversation | null,\r\n) {\r\n    const byId = new Map<string, AgentConversation>()\r\n    for (const conversation of conversations) {\r\n        if (belongsToAction(conversation, actionId, context)) byId.set(conversation.id, conversation)\r\n    }\r\n    if (liveConversation && belongsToAction(liveConversation, actionId, context)) byId.set(liveConversation.id, liveConversation)\r\n\r\n    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))\r\n}\r\n\r\n/** Own action popup state, injected services, and UI callbacks. */\r\nexport function useActionPopupController(input: ActionPopupControllerInput) {\r\n    const { action, context } = input\r\n    const configuredAgent = useConfigValueOrFallback('desktop.agent', '')\r\n    const configuredAgentProfiles = useConfigValueOrFallback('desktop.agentProfiles', [])\r\n    const configuredModel = useConfigValueOrFallback('desktop.model', '')\r\n    const configuredThinkingLevel = useConfigValueOrFallback('desktop.thinkingLevel', 'none')\r\n    const capabilities = useAgentCapabilities()\r\n    const sharedExecution = useActionExecution(action.id, context)\r\n    const convertPromptToAction = input.convertPromptToAction ?? defaultConvertPromptToAction\r\n    const cancelAction = input.cancelAction ?? defaultCancelAction\r\n    const answerQuestion = input.answerQuestion ?? defaultAnswerQuestion\r\n    const finishAction = input.finishAction ?? defaultFinishAction\r\n    const loadHistory = input.loadHistory ?? defaultLoadHistory\r\n    const loadConversation = input.loadConversation ?? defaultLoadConversation\r\n    const loadConversations = input.loadConversations ?? defaultLoadConversations\r\n    const preparePrompt = input.preparePrompt ?? defaultPreparePrompt\r\n    const runAction = input.runAction ?? defaultRunAction\r\n    const sendMessage = input.sendMessage ?? defaultSendMessage\r\n    const scheduleAction = input.scheduleAction ?? defaultScheduleAction\r\n    const promptContextKey = conversationContextKey(action.id, context)\r\n    const interactionKey = sharedExecution?.activeActionId\r\n        ? `${sharedExecution.executionId}\\u0000${sharedExecution.activeActionId}`\r\n        : promptContextKey\r\n    const sharedPromptDraft = actionExecutionService.getPromptDraft(action.id, context)\r\n    const initialPrompt = sharedPromptDraft || input.initialPrompt || ''\r\n    const promptKey = `${interactionKey}\\u0000${input.continueFrom ?? ''}\\u0000${input.initialPrompt ?? ''}`\r\n    const agentProfiles = mergeAgentProfiles(configuredAgentProfiles)\r\n    const defaultAgent = action.agent ?? configuredAgent\r\n    const defaultAgentProfile = findAgentProfile(agentProfiles, defaultAgent)\r\n    const defaultModel = (action.model ?? configuredModel) || (defaultAgentProfile ? defaultModelForProfile(defaultAgentProfile) : '')\r\n    const definitionThinkingLevel = validateThinkingLevel(action.thinkingLevel ?? configuredThinkingLevel, `action \"${action.label}\"`)\r\n    const [actionLabel, setActionLabel] = useState('')\r\n    const [agentOverride, setAgentOverride] = useState<string | null>(null)\r\n    const [convertMessage, setConvertMessage] = useState<string | null>(null)\r\n    const [conversationHistoryState, setConversationHistoryState] = useState<{ conversations: AgentConversation[], key: string }>({ conversations: [], key: '' })\r\n    const [promptState, setPromptState] = useState<{ key: string, status: PromptPreparationStatus, value: string }>({\r\n        key: promptKey,\r\n        status: action.type === 'agent' && !input.continueFrom ? 'loading' : 'ready',\r\n        value: initialPrompt,\r\n    })\r\n    // Bumped whenever the prompt is replaced externally (prepared, phrase, cleared) but\r\n    // never while typing, so an uncontrolled markdown editor can reseed only on real resets.\r\n    const [promptResetToken, setPromptResetToken] = useState(0)\r\n    const [localExecutionId, setLocalExecutionId] = useState<string | null>(null)\r\n    const [history, setHistory] = useState<ActionRunHistoryEntry[]>([])\r\n    const [historyError, setHistoryError] = useState<string | null>(null)\r\n    const [modelOverride, setModelOverride] = useState<string | null>(null)\r\n    const [localRunResult, setLocalRunResult] = useState<ActionRunResult | null>(null)\r\n    const [localRunStatus, setLocalRunStatus] = useState<PopupRunStatus>('idle')\r\n    const [scheduleMessage, setScheduleMessage] = useState<string | null>(null)\r\n    const [scheduleOpen, setScheduleOpen] = useState(false)\r\n    const [scheduleTimestamp, setScheduleTimestamp] = useState('')\r\n    const [liveActionKey, setLiveActionKey] = useState<string | null>(null)\r\n    const [selectedConversationState, setSelectedConversationState] = useState<{ conversation: AgentConversation | null, key: string }>({ conversation: null, key: '' })\r\n    const [thinkingLevelOverride, setThinkingLevelOverride] = useState<{ actionId: string, value: ThinkingLevel } | null>(null)\r\n    const actionRef = useRef(action)\r\n    const contextRef = useRef(context)\r\n    const selectionRequestRef = useRef(0)\r\n    const promptEditRevisionRef = useRef(0)\r\n    const promptRequestRef = useRef(0)\r\n    const agent = agentOverride ?? defaultAgent\r\n    const model = modelOverride ?? defaultModel\r\n    const selectedAgentProfile = findAgentProfile(agentProfiles, agent)\r\n    const selectedAgentModels = selectedAgentProfile?.models ?? []\r\n    const selectedAvailability = capabilities.availability.values[agent]\r\n    const agentAvailability = input.runAction\r\n        ? Object.fromEntries(agentProfiles.map((profile) => [profile.name, { available: true, error: null }]))\r\n        : capabilities.availability.values\r\n    const selectedAgentAvailable = !!input.runAction\r\n        || action.type !== 'agent'\r\n        || (!!selectedAvailability?.available && !capabilities.availability.error)\r\n    const backendAvailable = !!input.runAction || hasExecutionBackend()\r\n    const executionDisabledMessage = !backendAvailable\r\n        ? 'Action execution requires the Electron desktop app'\r\n        : action.type === 'agent' && capabilities.availability.loading\r\n            ? 'Checking agent executable availability'\r\n            : action.type === 'agent' && !selectedAgentAvailable\r\n                ? selectedAvailability?.error ?? capabilities.availability.error ?? `Agent executable is unavailable for ${agent}`\r\n                : null\r\n    const thinkingLevel = thinkingLevelOverride?.actionId === action.id ? thinkingLevelOverride.value : definitionThinkingLevel\r\n    const conversationKey = promptContextKey\r\n    const activePromptState: { key: string, status: PromptPreparationStatus, value: string } = promptState.key === promptKey\r\n        ? promptState\r\n        : {\r\n            key: promptKey,\r\n            status: action.type === 'agent' && !input.continueFrom && !sharedExecution ? 'loading' : 'ready',\r\n            value: sharedPromptDraft || input.initialPrompt || '',\r\n        }\r\n    const prompt = activePromptState.value\r\n    const promptPreparationPending = activePromptState.status === 'loading'\r\n    const promptPreparationFailed = activePromptState.status === 'failed'\r\n    const selectionKey = `${conversationKey}\\u0000${input.continueFrom ?? ''}`\r\n    const conversationHistory = conversationHistoryState.key === conversationKey ? conversationHistoryState.conversations : []\r\n    const conversationHistoryLoading = !!input.enableConversations && conversationHistoryState.key !== conversationKey\r\n    const selectedConversation = selectedConversationState.key === selectionKey ? selectedConversationState.conversation : null\r\n    const selectedHistory = selectedConversation ? [...conversationHistory, selectedConversation] : conversationHistory\r\n    const executionId = sharedExecution?.executionId ?? localExecutionId\r\n    const runStatus = sharedExecution?.status ?? localRunStatus\r\n    const runLogs = sharedExecution?.logs ?? localRunResult?.logs ?? []\r\n    const sessionActive = runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'\r\n    const agentActive = sessionActive && sharedExecution?.activeActionType === 'agent'\r\n    const streamingActive = agentActive && !!sharedExecution?.activeActionStreaming\r\n    const interactionReady = agentActive && !!sharedExecution?.interactionReady\r\n    const manualFinishAvailable = streamingActive && !sharedExecution?.activeActionAutoFinish\r\n    const showLiveConversation = !input.enableConversations\r\n        ? !!sharedExecution\r\n        : liveActionKey === conversationKey || runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'\r\n    const sharedAgentTurn = showLiveConversation ? sharedExecution?.agentTurn ?? null : null\r\n    const baseLiveConversation = sharedAgentTurn\r\n        ? selectedHistory.find(({ id }) => id === sharedAgentTurn.conversationId) ?? null\r\n        : null\r\n    const liveConversation = sharedAgentTurn\r\n        ? sharedExecution?.status !== 'running'\r\n            && sharedExecution?.status !== 'waitingForInput'\r\n            && baseLiveConversation?.status !== 'running'\r\n            && baseLiveConversation?.status !== 'waitingForInput'\r\n            ? baseLiveConversation\r\n            : liveAgentConversation(sharedAgentTurn, action.id, context, sharedExecution?.status ?? 'running', baseLiveConversation)\r\n        : null\r\n    const displayedConversation = liveConversation ?? selectedConversation\r\n    const conversations = mergeConversationHistory(selectedHistory, action.id, context, liveConversation)\r\n    const continuationReference = liveConversation?.path\r\n        ?? selectedConversation?.path\r\n        ?? input.continueFrom\r\n        ?? null\r\n    const isFollowUp = action.type === 'agent'\r\n        && (streamingActive || (runStatus !== 'queued' && runStatus !== 'running' && runStatus !== 'waitingForInput' && !!continuationReference))\r\n\r\n    useEffect(() => {\r\n        actionRef.current = action\r\n        contextRef.current = context\r\n    }, [action, context])\r\n\r\n    useEffect(() => {\r\n        const handlePromptDraftCleared = (event: Event) => {\r\n            const detail = (event as CustomEvent<{ actionId: string, executionId: string }>).detail\r\n            if (detail.executionId !== sharedExecution?.executionId) return\r\n            if (detail.actionId !== sharedExecution.activeActionId) return\r\n\r\n            setPromptState({ key: promptKey, status: 'ready', value: '' })\r\n            setPromptResetToken((token) => token + 1)\r\n        }\r\n        actionExecutionService.addEventListener('promptDraftCleared', handlePromptDraftCleared)\r\n\r\n        return () => actionExecutionService.removeEventListener('promptDraftCleared', handlePromptDraftCleared)\r\n    }, [promptKey, sharedExecution?.activeActionId, sharedExecution?.executionId])\r\n\r\n",
