design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:184:          "content": "import { cleanup, fireEvent, render, screen } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { configService } from '../../services/config/config_service'\nimport { AppThemeProvider } from '../../theme/theme_provider'\nimport { AgentChatFab } from './agent_chat_fab'\n\ndescribe('AgentChatFab', () => {\n    beforeEach(() => {\n        configService.init()\n        window.md2Actions = {\n            onActionExecution: vi.fn(() => vi.fn()),\n            prepareActionPrompt: vi.fn(async () => ({ prompt: '' })),\n        } as unknown as typeof window.md2Actions\n        Object.defineProperty(window, 'innerHeight', { configurable: true, value: 800 })\n        Object.defineProperty(window, 'innerWidth', { configurable: true, value: 1200 })\n    })\n\n    afterEach(() => {\n        cleanup()\n        delete window.md2Actions\n        configService.clear()\n    })\n\n    it('opens and closes project-wide run form on plain clicks', async () => {\n        render(<AgentChatFab />, { wrapper: AppThemeProvider })\n        const button = screen.getByRole('button', { name: 'Project agent' })\n\n        fireEvent.click(button)\n\n        expect(screen.getByRole('dialog', { name: 'Run actions' })).toBeInTheDocument()\n        expect(await screen.findByLabelText('Prompt')).toBeInTheDocument()\n        expect(screen.getByRole('combobox', { name: 'Conversation history' })).toBeInTheDocument()\n        expect(screen.getByLabelText('Conversation chat').compareDocumentPosition(screen.getByLabelText('Prompt')))\n            .toBe(Node.DOCUMENT_POSITION_FOLLOWING)\n        expect(document.querySelector('.MuiModal-root')).not.toBeInTheDocument()\n\n        fireEvent.click(button)\n\n        expect(screen.queryByRole('dialog', { name: 'Run actions' })).not.toBeInTheDocument()\n    })\n\n    it('moves without opening popup when pointer gesture crosses drag threshold', () => {\n        render(<AgentChatFab />, { wrapper: AppThemeProvider })\n        const button = screen.getByRole('button', { name: 'Project agent' })\n\n        fireEvent.pointerDown(button, { clientX: 1140, clientY: 740, pointerId: 1 })\n        fireEvent.pointerMove(button, { clientX: 900, clientY: 500, pointerId: 1 })\n        fireEvent.pointerUp(button, { pointerId: 1 })\n        fireEvent.click(button)\n\n        expect(button).toHaveStyle({ left: '888px', top: '488px' })\n        expect(screen.queryByRole('dialog', { name: 'Run actions' })).not.toBeInTheDocument()\n\n        fireEvent.click(button)\n        expect(screen.getByRole('dialog', { name: 'Run actions' })).toBeInTheDocument()\n    })\n\n    it('detaches the draggable popup while keeping its far corner fixed when resized from the top-left', () => {\n        render(<AgentChatFab />, { wrapper: AppThemeProvider })\n        const button = screen.getByRole('button', { name: 'Project agent' })\n        fireEvent.click(button)\n        const dialog = screen.getByRole('dialog', { name: 'Run actions' })\n        const handle = screen.getByRole('separator', { name: 'Resize action popup from top-left' })\n        dialog.getBoundingClientRect = vi.fn(() => new DOMRect(700, 200, 400, 450))\n\n        fireEvent.pointerDown(handle, { clientX: 100, clientY: 100, pointerId: 1 })\n        fireEvent.pointerMove(window, { clientX: 50, clientY: 40, pointerId: 1 })\n        fireEvent.pointerUp(window, { pointerId: 1 })\n\n        expect(button).toHaveStyle({ left: '1128px', top: '728px' })\n        expect(dialog.style.width).toBe('450px')\n        expect(dialog.style.height).toBe('510px')\n        expect(dialog).toHaveStyle({ left: '650px', position: 'fixed', top: '140px' })\n    })\n})\n\r\n",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:190:          "content": "[{\"path\":\"C:\\\\Users\\\\janbo\\\\Documents\\\\dev\\\\md2\\\\design\\\\feature_descriptions\\\\F_83_chatlog_sticky_at_end.md\",\"kind\":{\"type\":\"update\",\"move_path\":null},\"diff\":\"@@ -17,6 +17,22 @@\\n \\n-# Current status\\n+# Current state\\n+\\n+`ActionPopupContent` provides the chat scroll container. `ActionConversationChat` renders the selected or live conversation, but neither component tracks whether the viewport is at the end. Loading a conversation and streaming new content therefore leave the scroll position unchanged.\\n+\\n+# Implementation details\\n+\\n+- Make `ActionConversationChat` own its scroll viewport and bottom-stick state.\\n+- Treat a viewport within a small tolerance of its maximum scroll position as being at the end.\\n+- Start at the end when a conversation loads or the selected conversation changes.\\n+- After messages or streamed assistant content grow, scroll to the end only when the viewport was already at the end.\\n+- Update stickiness on user scroll. Scrolling up stops automatic movement; returning to the end enables it again.\\n+- Keep empty and shorter-than-viewport conversations at the end without errors.\\n \\n-# Details\\n+# Acceptance criteria\\n \\n-# Tasks\\n\\\\ No newline at end of file\\n+- Opening or selecting a conversation shows its latest content.\\n+- New messages and streamed content remain visible while the chat is at the end.\\n+- New content does not move the viewport after the user scrolls up.\\n+- Scrolling back to the end restores sticky behavior.\\n+- Behavior is shared by card and project agent popups.\\n+- Component tests cover initial load, conversation changes, content growth, opt-out, and reactivation.\\n\"}]",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:202:          "content": "diff --git a/design/feature_descriptions/F_83_chatlog_sticky_at_end.md b/design/feature_descriptions/F_83_chatlog_sticky_at_end.md\nindex 5b589f9..7d9f5e6 100644\n--- a/design/feature_descriptions/F_83_chatlog_sticky_at_end.md\n+++ b/design/feature_descriptions/F_83_chatlog_sticky_at_end.md\n@@ -15,8 +15,24 @@ after: 45d9a15f-7eaf-4993-8bf5-4606c21ec9c3\n \n when chatlog is loaded, auto scroll to end, keep it sticky at end while it is at end\n \n-# Current status\n+# Current state\n \n-# Details\n+`ActionPopupContent` provides the chat scroll container. `ActionConversationChat` renders the selected or live conversation, but neither component tracks whether the viewport is at the end. Loading a conversation and streaming new content therefore leave the scroll position unchanged.\n \n-# Tasks\n\\ No newline at end of file\n+# Implementation details\n+\n+- Make `ActionConversationChat` own its scroll viewport and bottom-stick state.\n+- Treat a viewport within a small tolerance of its maximum scroll position as being at the end.\n+- Start at the end when a conversation loads or the selected conversation changes.\n+- After messages or streamed assistant content grow, scroll to the end only when the viewport was already at the end.\n+- Update stickiness on user scroll. Scrolling up stops automatic movement; returning to the end enables it again.\n+- Keep empty and shorter-than-viewport conversations at the end without errors.\n+\n+# Acceptance criteria\n+\n+- Opening or selecting a conversation shows its latest content.\n+- New messages and streamed content remain visible while the chat is at the end.\n+- New content does not move the viewport after the user scrolls up.\n+- Scrolling back to the end restores sticky behavior.\n+- Behavior is shared by card and project agent popups.\n+- Component tests cover initial load, conversation changes, content growth, opt-out, and reactivation.\n",
