n    return {\n        actionId: 'action-review',\n        cardInternalId: 'card-1',\n        cardPath: 'design/F-1.md',\n        completedAt: '2026-07-15T10:01:00.000Z',\n        events: [],\n        hasExplicitTitle: true,\n        id: 'conversation-1',\n        messages: [],\n        path: 'design/activity/card__card-1.json#conversation=conversation-1',\n        providerSessions: [],\n        startedAt: '2026-07-15T10:00:00.000Z',\n        status: 'completed',\n        title: 'Review',\n        ...overrides,\n    }\n}\n\ndescribe('conversation picker data', () => {\n    it('uses explicit titles with local date/time and falls back to date/time alone', () => {\n        const titled = conversation()\n        const untitled = conversation({ hasExplicitTitle: false, title: 'conversation-1' })\n\n        expect(conversationPickerLabel(titled)).toBe(`Review â€” ${formatConversationDateTime(titled.startedAt)}`)\n        expect(conversationPickerLabel(untitled)).toBe(formatConversationDateTime(untitled.startedAt))\n        expect(formatConversationDateTime('invalid timestamp')).toBe('invalid timestamp')\n    })\n\n    it('filters context, sorts newest first, and replaces live duplicates', () => {\n        const context: ActionContext = { cardInternalId: 'card-1', file: 'design/F-1.md', kind: 'card' }\n        const older = conversation({ id: 'older', path: 'older.json', startedAt: '2026-07-14T10:00:00.000Z' })\n        const newest = conversation({ id: 'newest', path: 'newest.json', startedAt: '2026-07-15T10:00:00.000Z' })\n        const otherAction = conversation({ actionId: 'action-implement', id: 'other-action', path: 'other-action.json' })\n        const otherCard = conversation({ cardInternalId: 'card-2', cardPath: 'design/F-2.md', id: 'other', path: 'other.json' })\n        const liveNewest = conversation({ id: 'newest', messages: [{ content: 'live', id: 'm1', role: 'assistant', timestamp: 'now' }], path: 'live-newest.json' })\n\n        const result = mergeConversationHistory([older, newest, otherAction, otherCard], 'action-review', context, liveNewest)\n\n        expect(result.map(({ id }) => id)).toEqual(['newest', 'older'])\n        expect(result[0].messages[0].content).toBe('live')\n    })\n\n    it('keeps project conversations separate from card conversations', () => {\n        const projectConversation = conversation({ cardInternalId: null, cardPath: null, id: 'project', path: 'project.json' })\n\n        expect(mergeConversationHistory([conversation(), projectConversation], 'action-review', { kind: 'project' }, null))\n            .toEqual([projectConversation])\n    })\n})\n\r\nimport { act, cleanup, render, screen } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { formatDuration } from './conversation_duration'\nimport { ConversationTimer } from './conversation_timer'\n\ndescribe('formatDuration', () => {\n    it('formats sub-minute spans as m:ss', () => {\n        expect(formatDuration(7_000)).toBe('0:07')\n    })\n\n    it('formats minute spans as m:ss', () => {\n        expect(formatDuration(83_000)).toBe('1:23')\n    })\n\n    it('formats hour spans as h:mm:ss', () => {\n        expect(formatDuration(3_753_000)).toBe('1:02:33')\n    })\n\n    it('clamps negative spans to zero', () => {\n        expect(formatDuration(-5_000)).toBe('0:00')\n    })\n})\n\ndescribe('ConversationTimer', () => {\n    beforeEach(() => {\n        vi.useFakeTimers()\n        vi.setSystemTime(new Date('2026-01-01T00:00:05.000Z'))\n    })\n\n    afterEach(() => {\n        cleanup()\n        vi.useRealTimers()\n    })\n\n    it('freezes at the completed duration when the run is done', () => {\n        render(\n            <ConversationTimer completedAt=\"2026-01-01T00:01:30.000Z\" startedAt=\"2026-01-01T00:00:00.000Z\" />,\n        )\n\n        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('1:30')\n    })\n\n    it('ticks once a second while the run is active', () => {\n        render(<ConversationTimer completedAt={null} startedAt=\"2026-01-01T00:00:00.000Z\" />)\n\n        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:05')\n\n        act(() => {\n            vi.advanceTimersByTime(3_000)\n        })\n\n        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:08')\n    })\n})\n\r\n\r\n\r\n",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:354:          "content": "[{\"path\":\"C:\\\\Users\\\\janbo\\\\Documents\\\\dev\\\\md2\\\\app\\\\src\\\\components\\\\actions\\\\action_conversation_chat.tsx\",\"kind\":{\"type\":\"update\",\"move_path\":null},\"diff\":\"@@ -1,3 +1,3 @@\\n import { Box, Stack, Typography } from '@mui/material'\\n-import { useEffect } from 'react'\\n+import { useEffect, useLayoutEffect, useRef, type UIEvent } from 'react'\\n import ReactMarkdown from 'react-markdown'\\n@@ -11,2 +11,5 @@\\n \\n+const CHAT_END_TOLERANCE = 4\\n+const MIN_CHAT_HEIGHT = 96\\n+\\n interface ActionConversationChatProps {\\n@@ -17,2 +20,6 @@\\n \\n+function viewportIsAtEnd(viewport: HTMLDivElement) {\\n+    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE\\n+}\\n+\\n /** Ordered user/assistant transcript shown above the popup prompt. */\\n@@ -22,3 +29,10 @@\\n     const messages = conversation?.messages.filter(({ role }) => role === 'user' || role === 'assistant') ?? []\\n+    const viewportRef = useRef<HTMLDivElement>(null)\\n+    const conversationPathRef = useRef<string | null | undefined>(undefined)\\n+    const stuckToEndRef = useRef(true)\\n \\n+    const handleScroll = (event: UIEvent<HTMLDivElement>) => {\\n+        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)\\n+    }\\n+\\n     useEffect(() => {\\n@@ -29,4 +43,23 @@\\n \\n+    useLayoutEffect(() => {\\n+        const viewport = viewportRef.current\\n+        if (!viewport) return\\n+\\n+        const conversationPath = conversation?.path ?? null\\n+        const conversationChanged = conversationPathRef.current !== conversationPath\\n+        conversationPathRef.current = conversationPath\\n+        if (conversationChanged) stuckToEndRef.current = true\\n+        if (!stuckToEndRef.current) return\\n+\\n+        viewport.scrollTop = viewport.scrollHeight\\n+    })\\n+\\n     return (\\n-        <Stack aria-label=\\\"Conversation chat\\\" spacing={1} sx={{ minHeight: 72 }}>\\n+        <Stack\\n+            aria-label=\\\"Conversation chat\\\"\\n+            onScroll={handleScroll}\\n+            ref={viewportRef}\\n+            spacing={1}\\n+            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowY: 'auto' }}\\n+        >\\n             {messages.map((message) => (\\n\"},{\"path\":\"C:\\\\Users\\\\janbo\\\\Documents\\\\dev\\\\md2\\\\app\\\\src\\\\components\\\\actions\\\\action_popup_content.tsx\",\"kind\":{\"type\":\"update\",\"move_path\":null},\"diff\":\"@@ -34,3 +34,2 @@\\n export const PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY = 'md2.projectAgentPopupSize'\\n-const MIN_CHAT_HEIGHT = 96\\n \\n@@ -240,9 +239,7 @@\\n                         </Box>\\n-                        <Box sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowY: 'auto' }}>\\n-                            <ActionConversationChat\\n-                                conversation={controller.displayedConversation}\\n-                                onConversationViewed={props.onConversationViewed}\\n-                                status={controller.runStatus}\\n-                            />\\n-                        </Box>\\n+                        <ActionConversationChat\\n+                            conversation={controller.displayedConversation}\\n+                            onConversationViewed={props.onConversationViewed}\\n+                            status={controller.runStatus}\\n+                        />\\n                         <ActionAgentPrompt\\n\"}]",
design\activity\card__31eb5a7b-6d2b-407c-a83f-8e6c9c0201f3.json:360:          "content": "[{\"path\":\"C:\\\\Users\\\\janbo\\\\Documents\\\\dev\\\\md2\\\\app\\\\src\\\\components\\\\actions\\\\action_conversation_chat.test.tsx\",\"kind\":{\"type\":\"add\"},\"diff\":\"import { cleanup, fireEvent, render, screen } from '@testing-library/react'\\nimport { afterEach, beforeEach, describe, expect, it } from 'vitest'\\nimport type { AgentConversation, AgentConversationMessage } from '../../data/data_types'\\nimport { AppThemeProvider } from '../../theme/theme_provider'\\nimport { ActionConversationChat } from './action_conversation_chat'\\n\\nlet clientHeight = 100\\nlet scrollHeight = 300\\nlet scrollPositions = new WeakMap<HTMLElement, number>()\\nconst originalClientHeight = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'clientHeight')\\nconst originalScrollHeight = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'scrollHeight')\\nconst originalScrollTop = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'scrollTop')\\n\\nfunction message(id: string, content: string): AgentConversationMessage {\\n    return { content, id, role: 'assistant', timestamp: '2026-07-27T10:00:00.000Z' }\\n}\\n\\nfunction conversation(path: string, messages: AgentConversationMessage[]): AgentConversation {\\n    return {\\n        actionId: 'review',\\n        cardInternalId: 'card-1',\\n        cardPath: 'design/F-83.md',\\n        completedAt: '2026-07-27T10:01:00.000Z',\\n        events: [],\\n        hasExplicitTitle: true,\\n        id: path,\\n        messages,\\n        path,\\n        providerSessions: [],\\n        startedAt: '2026-07-27T10:00:00.000Z',\\n        status: 'completed',\\n        title: path,\\n    }\\n}\\n\\nfunction renderChat(value: AgentConversation | null) {\\n    return render(\\n        <AppThemeProvider>\\n            <ActionConversationChat conversation={value} status=\\\"idle\\\" />\\n        </AppThemeProvider>,\\n    )\\n}\\n\\nfunction restoreProperty(name: 'clientHeight' | 'scrollHeight' | 'scrollTop', descriptor?: PropertyDescriptor) {\\n    if (descriptor) {\\n        Object.defineProperty(HTMLElement.prototype, name, descriptor)\\n        return\\n    }\\n\\n    delete HTMLElement.prototype[name]\\n}\\n\\ndescribe('ActionConversationChat', () => {\\n    beforeEach(() => {\\n        clientHeight = 100\\n        scrollHeight = 300\\n        scrollPositions = new WeakMap<HTMLElement, number>()\\n        Object.defineProperty(HTMLElement.prototype, 'clientHeight', { configurable: true, get: () => clientHeight })\\n        Object.defineProperty(HTMLElement.prototype, 'scrollHeight', { configurable: true, get: () => scrollHeight })\\n        Object.defineProperty(HTMLElement.prototype, 'scrollTop', {\\n            configurable: true,\\n            get() {\\n                return scrollPositions.get(this) ?? 0\\n            },\\n            set(value: number) {\\n                const maximumScrollTop = Math.max(0, scrollHeight - clientHeight)\\n                scrollPositions.set(this, Math.max(0, Math.min(value, maximumScrollTop)))\\n            },\\n        })\\n    })\\n\\n    afterEach(() => {\\n        cleanup()\\n        restoreProperty('clientHeight', originalClientHeight)\\n        restoreProperty('scrollHeight', originalScrollHeight)\\n        restoreProperty('scrollTop', originalScrollTop)\\n    })\\n\\n    it('starts at the end when a conversation loads', () => {\\n        renderChat(conversation('first.json', [message('message-1', 'First')]))\\n\\n        expect(screen.getByLabelText('Conversation chat').scrollTop).toBe(200)\\n    })\\n\\n    it('returns to the end when the selected conversation changes', () => {\\n        const first = conversation('first.json', [message('message-1', 'First')])\\n        const second = conversation('second.json', [message('message-2', 'Second')])\\n        const { rerender } = renderChat(first)\\n        const viewport = screen.getByLabelText('Conversation chat')\\n        viewport.scrollTop = 40\\n        fireEvent.scroll(viewport)\\n\\n        rerender(\\n            <AppThemeProvider>\\n                <ActionConversationChat conversation={second} status=\\\"idle\\\" />\\n            </AppThemeProvider>,\\n        )\\n\\n        expect(viewport.scrollTop).toBe(200)\\n    })\\n\\n    it('keeps new content visible while stuck to the end', () => {\\n        const first = conversation('first.json', [message('message-1', 'First')])\\n        const grown = conversation('first.json', [message('message-1', 'First'), message('message-2', 'Second')])\\n        const { rerender } = renderChat(first)\\n        const viewport = screen.getByLabelText('Conversation chat')\\n        scrollHeight = 400\\n\\n        rerender(\\n            <AppThemeProvider>\\n                <ActionConversationChat conversation={grown} status=\\\"idle\\\" />\\n            </AppThemeProvider>,\\n        )\\n\\n        expect(viewport.scrollTop).toBe(300)\\n    })\\n\\n    it('does not move when new content arrives after the user scrolls up', () => {\\n        const first = conversation('first.json', [message('message-1', 'First')])\\n        const grown = conversation('first.json', [message('message-1', 'First'), message('message-2', 'Second')])\\n        const { rerender } = renderChat(first)\\n        const viewport = screen.getByLabelText('Conversation chat')\\n        viewport.scrollTop = 40\\n        fireEvent.scroll(viewport)\\n        scrollHeight = 400\\n\\n        rerender(\\n            <AppThemeProvider>\\n                <ActionConversationChat conversation={grown} status=\\\"idle\\\" />\\n            </AppThemeProvider>,\\n        )\\n\\n        expect(viewport.scrollTop).toBe(40)\\n    })\\n\\n    it('restores sticky behavior after the user returns within the end tolerance', () => {\\n        const first = conversation('first.json', [message('message-1', 'First')])\\n        const grown = conversation('first.json', [message('message-1', 'First'), message('message-2', 'Second')])\\n        const { rerender } = renderChat(first)\\n        const viewport = screen.getByLabelText('Conversation chat')\\n        viewport.scrollTop = 196\\n        fireEvent.scroll(viewport)\\n        scrollHeight = 400\\n\\n        rerender(\\n            <AppThemeProvider>\\n                <ActionConversationChat conversation={grown} status=\\\"idle\\\" />\\n            </AppThemeProvider>,\\n        )\\n\\n        expect(viewport.scrollTop).toBe(300)\\n    })\\n\\n    it('keeps empty content at the end when it is shorter than the viewport', () => {\\n        clientHeight = 200\\n        scrollHeight = 80\\n        const { rerender } = renderChat(null)\\n        const viewport = screen.getByLabelText('Conversation chat')\\n        fireEvent.scroll(viewport)\\n        scrollHeight = 100\\n\\n        rerender(\\n            <AppThemeProvider>\\n                <ActionConversationChat conversation={conversation('empty.json', [])} status=\\\"idle\\\" />\\n            </AppThemeProvider>,\\n        )\\n\\n        expect(viewport.scrollTop).toBe(0)\\n    })\\n})\\n\"}]",
